// DESCRIPTION: Unified Modal Auto-Open Handler
// SOURCE: Generated by Gemini AI
// DATE: July 24, 2026

document.addEventListener("DOMContentLoaded", function () {
    const urlParams = new URLSearchParams(window.location.search);

    // 1. Sub-Admin Modal (e.g., sub-admin.php?empty=1 or ?mismatch=1)
    if (urlParams.has('empty') || urlParams.has('mismatch')) {
        const subAdminModalElement = document.getElementById('addSubAdminModal');
        if (subAdminModalElement && typeof bootstrap !== 'undefined') {
            const subAdminModal = bootstrap.Modal.getOrCreateInstance(subAdminModalElement);
            subAdminModal.show();
            cleanUrlParams();
        }
    }

    // 2. Menu Items Modal (e.g., menu-items.php?empty=1)
    if (urlParams.has('empty')) {
        const itemModalElement = document.getElementById('additemsModal');
        if (itemModalElement && typeof bootstrap !== 'undefined') {
            const itemModal = bootstrap.Modal.getOrCreateInstance(itemModalElement);
            itemModal.show();
            cleanUrlParams();
        }
    }

    // Helper function to remove query parameters from URL without reloading page
    function cleanUrlParams() {
        const cleanUrl = window.location.protocol + "//" + window.location.host + window.location.pathname;
        window.history.replaceState({ path: cleanUrl}, '', cleanUrl);
    }
});